"""Reference page checks (contract v4): 5 sections, fused anchors, explorers."""
import sys
from playwright.sync_api import sync_playwright
BASE="http://127.0.0.1:8137"; results=[]; failures=[]
def ok(n,c): results.append(("PASS " if c else "FAIL ")+n); failures.append(n) if not c else None
with sync_playwright() as pw:
    try: b=pw.chromium.launch(channel="chrome")
    except Exception: b=pw.chromium.launch()
    p=b.new_page(viewport={"width":1440,"height":950}); errs=[]
    p.on("pageerror",lambda e: errs.append(str(e))); p.on("console",lambda m: errs.append(m.text) if m.type=="error" else None)
    r=p.goto(BASE+"/reference/",wait_until="networkidle"); p.wait_for_timeout(300)
    ok("reference 200",r.status==200); ok("reference H1","what you agree on today" in p.locator("h1").text_content().lower())
    # v4: exactly five main sections in contract order
    order=p.evaluate("[...document.querySelectorAll('main > section[id]')].map(s=>s.id).join(',')")
    ok("five sections order","workflow,dimensions,artifacts,format,compatibility"==order)
    ok("section-nav restored reference",p.locator(".section-nav").is_visible())
    ok("no ref-nav",p.locator(".ref-nav").count()==0)
    ok("sections share the viewport floor",p.evaluate("[...document.querySelectorAll('main > section[id]')].map(s=>getComputedStyle(s).minHeight).every((v,i,a)=>v===a[0]&&v!='0px')"))
    # workflow: four stages with meta info, equitably distributed, no map switch
    ok("workflow stages",p.locator("#workflow .step").count()==4)
    ok("step meta info",p.locator("#workflow .step-meta").count()==4)
    ok("step fonts +15%",float(p.evaluate("getComputedStyle(document.querySelector('#workflow .step-title')).fontSize").rstrip('px'))>=17 and float(p.evaluate("getComputedStyle(document.querySelector('#workflow .step-desc')).fontSize").rstrip('px'))>=15)
    hs=p.evaluate("[...document.querySelectorAll('#workflow .step')].map(e=>e.offsetHeight)")
    ok("steps equal height",len(hs)==4 and max(hs)-min(hs)<=2)
    ok("steps natural height",p.evaluate("getComputedStyle(document.querySelector('#workflow .workflow-grid')).minHeight")=="auto")
    ok("workflow settles on screen",p.locator("#workflow").evaluate("e=>e.classList.contains('is-live')") and p.locator("#workflow .step").first.evaluate("e=>e.getAnimations().some(a=>a.animationName=='settle')"))
    ok("active step carries depth",p.locator('#workflow .step[aria-pressed="true"]').evaluate("e=>getComputedStyle(e).filter").startswith("drop-shadow") and p.locator('#workflow .step[aria-pressed="false"]').first.evaluate("e=>getComputedStyle(e).filter")=="none")
    ok("no wf map switch",p.locator("[data-wf-view]").count()==0 and p.locator(".wf-map").count()==0 and p.locator("#map-data").count()==0)
    p.locator('#workflow .step[data-step="2"]').click(); p.wait_for_timeout(200)
    ok("workflow step select","Carry out the work" in p.locator("#step-heading").text_content())
    ok("step detail is modal",p.locator("#step-dialog").evaluate("el=>el.open") and p.locator(".step-detail").count()==0)
    ok("step dialog legible",float(p.evaluate("parseFloat(getComputedStyle(document.querySelector('#step-dialog .detail-item span')).fontSize)"))>=15)
    p.keyboard.press("Escape"); p.wait_for_timeout(150)
    ok("step dialog closes",not p.locator("#step-dialog").evaluate("el=>el.open"))
    # fused anchors: learning inside artifacts, continue inside compatibility, intro alias
    ok("learning subsection","does not make it an active rule" in p.locator("#artifacts #learning").text_content())
    ok("learning not a section",p.locator("section#learning").count()==0)
    ok("continue cta","Verify the first task" in p.locator("#compatibility #continue").text_content() and "See how to connect an agent" in p.locator("#compatibility #continue").text_content())
    ok("continue not a section",p.locator("section#continue").count()==0)
    ok("closing band has its own surface",p.locator("#compatibility .compat-cta").evaluate("e=>{const s=getComputedStyle(e);return s.backgroundColor!=='rgba(0, 0, 0, 0)'&&parseFloat(s.borderTopWidth)>=1}") and p.locator("#compatibility .compat-cta").evaluate("e=>getComputedStyle(e).backgroundColor")!=p.locator("#compatibility").evaluate("e=>getComputedStyle(e).backgroundColor"))
    ok("intro alias",p.locator("#intro").count()==1)
    anchors=p.evaluate("['intro','workflow','dimensions','artifacts','learning','format','compatibility','continue'].map(a=>!!document.getElementById(a))")
    ok("all anchors resolve",all(anchors))
    ok("learning visible",p.locator("#artifacts #learning").is_visible())
    ok("continue visible",p.locator("#compatibility #continue").is_visible())
    # dimensions: hexagon menu is the only selector — numbered cards removed, 30/70 layout
    ok("no numbered cards",p.locator("#dimensions .dimension").count()==0 and p.locator("#dimensions .dimension-list").count()==0 and p.locator("#dimensions .dim-cards").count()==0)
    ok("six hex nodes",p.locator("#dimensions .hex-node").count()==6)
    ok("node accessible names",p.locator("#dimensions .hex-node[aria-label]").count()==6 and p.locator("#dimensions .hex-node title").count()==0)
    ok("dim head in left col",p.locator("#dimensions .dim-head .section-head").count()==1)
    cols=p.evaluate("()=>{const g=document.querySelector('#dimensions .hex-layout');const w=g.getBoundingClientRect().width;const cs=getComputedStyle(g).gridTemplateColumns.split(' ').map(parseFloat);return [cs[0]/w,cs[1]/w]}")
    ok("left col <=30%",cols[0]<=0.31)
    ok("menu >=80% of visual",p.evaluate("document.querySelector('#dimensions .hex-map').getBoundingClientRect().width/document.querySelector('#dimensions .hex-visual').getBoundingClientRect().width")>=0.8)
    ok("hex visual logo",p.locator("#dimensions .hex-visual .hex-map").count()==1 and p.locator("#dimensions .hex-visual .dim-logo").count()==1)
    ok("menu top-aligned",p.evaluate("()=>{const a=document.querySelector('#dimensions .hex-map').getBoundingClientRect(),b=document.querySelector('#dimensions .hex-visual').getBoundingClientRect();return a.top-b.top<4&&b.top-a.top<4}"))
    p.evaluate("document.querySelector('#dimensions').scrollIntoView()"); p.wait_for_timeout(1700)
    ok("menu entrance played",p.locator("#dimensions .hex-visual.entered").count()==1)
    ok("logo entrance zoom",p.evaluate("getComputedStyle(document.querySelector('#dimensions .dim-logo')).animationName")=="logo-zoom")
    ok("node entrance spin",p.evaluate("getComputedStyle(document.querySelector('#dimensions .hex-node')).animationName")=="node-spin")
    ok("all nodes visible after entry",p.evaluate("[...document.querySelectorAll('#dimensions .hex-node')].every(n=>getComputedStyle(n).opacity=='1')"))
    ok("hex lines stay green",p.evaluate("""()=>{const e=getComputedStyle(document.querySelector('#dimensions .hex-edge')).stroke;const q=getComputedStyle(document.querySelector('#dimensions .hex-path')).stroke;return e==q&&e=='rgb(23, 111, 98)'}"""))
    ok("no hover tip cards",p.locator("#dimensions .hex-tip").count()==0)
    ok("six dimension names visible",p.locator("#dimensions .hex-labels text").count()==6 and all(len((t.text_content() or "").strip())>2 for t in p.locator("#dimensions .hex-labels text").all()))
    ok("chips exist hidden on desktop",p.locator("#dimensions .dim-chip").count()==6 and not p.locator("#dimensions .dim-chips").is_visible())
    p.locator('#dimensions .hex-node[data-dimension="2"]').click(); p.wait_for_timeout(600)
    ok("hex node selects","context" in p.locator("#artifact-name").text_content().lower())
    ok("aria pressed on node",p.locator('#dimensions .hex-node[data-dimension="2"]').get_attribute("aria-pressed")=="true")
    ok("bullseye kept on select",p.evaluate("""()=>{const n=document.querySelector('#dimensions .hex-node[data-dimension="2"]');const r=[...n.querySelectorAll('circle')].map(c=>parseFloat(getComputedStyle(c).r));return r[0]>r[1]&&r[1]>=16}"""))
    ok("selected node carries depth",p.locator('#dimensions .hex-node[aria-pressed="true"] circle:not(.hex-hit)').first.evaluate("e=>getComputedStyle(e).filter").startswith("drop-shadow") and p.locator('#dimensions .hex-node[aria-pressed="false"] circle:not(.hex-hit)').first.evaluate("e=>getComputedStyle(e).filter")=="none")
    ok("detail fonts +40%",float(p.evaluate("getComputedStyle(document.querySelector('#dimensions .ficha-rows dd')).fontSize").rstrip('px'))>=17.4)
    ok("logo pulse on select",p.locator("#dimensions .dim-logo image.pulse").count()==1)
    ok("single outer hexagon",p.locator("#dimensions .hex-edge").count()==1)
    ok("ring >=15% smaller",p.evaluate("document.querySelector('#dimensions .hex-edge').getBoundingClientRect().width/document.querySelector('#dimensions .hex-map').getBoundingClientRect().width")<=0.60)
    ok("logo size unchanged",abs(p.evaluate("document.querySelector('#dimensions .dim-logo image').getBoundingClientRect().width/document.querySelector('#dimensions .hex-map').getBoundingClientRect().width")-0.486)<0.01)
    ok("logo inside svg",p.locator("#dimensions svg .dim-logo image").count()==1)
    ok("menu sinks on select",p.locator("#dimensions .hex-visual.is-detail").count()==1)
    ok("focus moves to detail",p.evaluate("document.activeElement.classList.contains('artifact-preview')"))
    ok("detail is region not dialog",p.locator("#dimensions .artifact-preview").get_attribute("role")=="region" and p.locator("#dimensions .artifact-preview").get_attribute("aria-live") is None)
    ok("close btn >=44px",p.evaluate("(()=>{const r=document.querySelector('#dimensions .dim-preview-close').getBoundingClientRect();return r.width>=44&&r.height>=44})()"))
    mapvis=p.evaluate("()=>{const c=getComputedStyle(document.querySelector('#dimensions .hex-map'));return c.visibility!='hidden'&&parseFloat(c.opacity)>0.05}")
    ok("map hidden behind detail",not mapvis)
    ok("dim-head stays visible",p.locator("#dimensions .dim-head").is_visible())
    pv=p.evaluate("""()=>{const a=document.querySelector('#dimensions .artifact-preview').getBoundingClientRect(),v=document.querySelector('#dimensions .hex-visual').getBoundingClientRect();return {pos:getComputedStyle(document.querySelector('#dimensions .artifact-preview')).position,dx:Math.abs(a.x-v.x)+Math.abs(a.width-v.width),top:Math.abs(a.y-v.y),z:getComputedStyle(document.querySelector('#dimensions .artifact-preview')).zIndex}}""")
    ok("detail overlays visual full width",pv["pos"]=="absolute" and pv["dx"]<8 and pv["top"]<12 and int(pv["z"])>=6)
    ok("detail shows all info directly",p.evaluate("document.querySelector('#dim-benefit').textContent.length>10") and p.locator("#dimensions .dim-tech-toggle").count()==0 and p.locator("#dimensions .artifact-preview details").count()==0 and p.locator("#dimensions #ficha-fn").is_visible())
    ok("detail auto height no inner scroll",p.evaluate("(()=>{const a=document.querySelector('#dimensions .artifact-preview');return a.scrollHeight<=a.clientHeight+4})()"))
    ok("active label marked",p.locator("#dimensions .hex-labels text.is-active").count()==1)
    ok("scope note in closed details",p.evaluate("!!document.querySelector('#dimensions details.dim-scope-detail')") and not p.locator("#dimensions details.dim-scope-detail").evaluate("el=>el.open") and p.evaluate("!document.querySelector('#dimensions .dimensions-scope')") and p.locator("#dimensions .dim-q-summary .dim-footer").count()==0)
    p.locator("#dimensions .dim-preview-close").click(); p.wait_for_timeout(250)
    ok("detail closes, menu replays",p.locator("#dimensions .hex-visual.is-detail").count()==0 and p.locator("#dimensions .hex-visual.replay").count()==1)
    ok("focus returns to node",p.evaluate("document.activeElement.dataset.dimension=='2'"))
    p.wait_for_timeout(1400)
    ok("replay animation clears",p.locator("#dimensions .hex-visual.replay").count()==0)
    # keyboard path: Enter selects, Escape closes and refocuses trigger
    p.locator('#dimensions .hex-node[data-dimension="3"]').press("Enter"); p.wait_for_timeout(400)
    ok("enter selects + focus detail",p.locator("#dimensions .hex-visual.is-detail").count()==1 and p.evaluate("document.activeElement.classList.contains('artifact-preview')"))
    p.keyboard.press("Escape"); p.wait_for_timeout(250)
    ok("escape closes + refocus node",p.locator("#dimensions .hex-visual.is-detail").count()==0 and p.evaluate("document.activeElement.dataset.dimension=='3'"))
    # workflow: first-section entrance animation + modal detail
    ok("workflow rise-in",p.locator("#workflow .rise-in").count()==1)
    # dimensions: single-viewport composition
    ok("dimensions viewport height",p.evaluate("document.querySelector('#dimensions').getBoundingClientRect().height")>=p.evaluate("window.innerHeight-72-5"))
    ok("seven artifacts",p.locator("#artifacts .artifact-node").count()==7)
    ok("artifacts wait for the viewport",p.locator("#artifacts .artifact-node").first.evaluate("e=>e.getAnimations().length")==0 and not p.locator("#artifacts").evaluate("e=>e.classList.contains('is-live')"))
    p.locator("#artifacts").scroll_into_view_if_needed(); p.wait_for_timeout(200)
    ok("artifacts staggered on entry",p.locator("#artifacts .artifact-node").evaluate_all("els=>els.map(e=>getComputedStyle(e).animationDelay)")==["0s","0.05s","0.1s","0.15s","0.2s","0.25s","0.3s"])
    p.wait_for_timeout(700)
    ok("artifacts lift on hover",p.locator("#artifacts .artifact-node").first.evaluate("e=>getComputedStyle(e).transition").find("transform")>=0)
    ok("selected artifact carries depth",p.locator('#artifacts .artifact-node[aria-pressed="true"]').evaluate("e=>getComputedStyle(e).filter").startswith("drop-shadow"))
    p.locator('#artifacts .artifact-node[data-artifact="1"]').click(); p.wait_for_timeout(200)
    ok("artifact selection",p.locator("#art-title").text_content()=="meta-brain.cortex")
    # format: one comparator, editable demo and benefit cards removed
    ok("codec comparator",p.locator("#format .codec-grid .code-panel").count()==2)
    ok("codec demo removed",p.locator("#idea-input").count()==0 and p.locator(".codec-play").count()==0 and p.locator("#format .codec-cards").count()==0)
    ok("codec certificate",p.locator("#format .codec-certificate a").count()==2)
    ok("format disclosures",p.locator("#format details.ev-detail").count()==1)
    ok("format detail dark surface",p.evaluate("getComputedStyle(document.querySelector('#format details.ev-detail')).backgroundColor")=="rgb(16, 31, 44)" and p.evaluate("getComputedStyle(document.querySelector('#format details.ev-detail > summary')).color")=="rgb(250, 249, 245)")
    p.locator('#format details.ev-detail summary').click(); p.wait_for_timeout(150)
    ok("format disclosure opens","alias" in p.locator("#format details.ev-detail").text_content())
    # compatibility: two disclosures hold the long tables
    ok("compat disclosures",p.locator("#compatibility details.ev-detail").count()==2)
    ok("compat route modules",p.locator("#compatibility .compat-route").count()==2)
    ok("compat h2 project not agent","Governance belongs to the project" in p.locator("#compatibility .section-head h2").text_content())
    ok("scope label not consumer","Scope" in [s.text_content().strip() for s in p.locator("#artifacts .artifact-meta small").all()][2])
    ok("compatibility tables hidden",p.locator("#compatibility .compat-table:visible").count()==0)
    p.locator('#compatibility details.ev-detail summary').first.click(); p.wait_for_timeout(150)
    ok("compat tables in disclosure",p.locator("#compatibility details.ev-detail").first.locator(".compat-table").count()==2)
    ok("projection targets table",p.locator("#compatibility .compat-table").nth(0).locator("tbody tr").count()==4)
    ok("harness matrix table",p.locator("#compatibility .compat-table").nth(1).locator("tbody tr").count()==9)
    ok("no console errors",len(errs)==0)
    missing=p.evaluate("""()=>{const defs=new Set(),uses=[];const scan=(css)=>{for(const m of css.matchAll(/(--[\\w-]+)\\s*:/g))defs.add(m[1]);for(const m of css.matchAll(/var\\(\\s*(--[\\w-]+)\\s*([,)])/g))uses.push({v:m[1],fb:m[2]===','})};for(const sh of document.styleSheets){try{for(const r of sh.cssRules)scan(r.cssText||'')}catch(e){}}document.querySelectorAll('[style]').forEach(el=>{for(const m of (el.getAttribute('style')||'').matchAll(/(--[\\w-]+)\\s*:/g))defs.add(m[1])});return [...new Set(uses.filter(u=>!u.fb&&!defs.has(u.v)).map(u=>u.v))]}""")
    ok("no undefined css vars",missing==[])
    p.evaluate("location.hash='#intro'"); p.wait_for_timeout(700)
    ok("intro alias focuses visible h1",p.evaluate("document.activeElement.tagName")=="H1" and "what you agree on today" in (p.evaluate("document.activeElement.textContent") or "").lower())
    # ES mirror: same five-section structure
    q=b.new_page(viewport={"width":1440,"height":950}); q.goto(BASE+"/es/referencia/",wait_until="networkidle")
    ok("ES five sections","workflow,dimensions,artifacts,format,compatibility"==q.evaluate("[...document.querySelectorAll('main > section[id]')].map(s=>s.id).join(',')"))
    ok("ES anchors",all(q.evaluate("['intro','workflow','dimensions','artifacts','learning','format','compatibility','continue'].map(a=>!!document.getElementById(a))")))
    ok("ES chips + labels contract",q.locator("#dimensions .dim-chip").count()==6 and q.locator("#dimensions .hex-labels text").count()==6)
    ok("ES scope label","Ámbito" in [s.text_content().strip() for s in q.locator("#artifacts .artifact-meta small").all()][2])
    ok("ES compat h2","gobierno pertenece al proyecto" in q.locator("#compatibility .section-head h2").text_content().lower())
    q.close()
    m=b.new_page(viewport={"width":390,"height":844}); m.goto(BASE+"/reference/",wait_until="networkidle")
    m.locator("#dimensions").scroll_into_view_if_needed(); m.wait_for_timeout(300)
    ok("mobile chips visible",m.locator("#dimensions .dim-chips").is_visible() and m.locator("#dimensions .dim-chip").count()==6)
    ok("mobile svg labels hidden",not m.locator("#dimensions .hex-labels").is_visible())
    ok("mobile no overflow",m.evaluate("document.documentElement.scrollWidth-window.innerWidth")==0)
    m.locator('#dimensions .dim-chip[data-dimension="1"]').click(); m.wait_for_timeout(400)
    ok("mobile detail in flow",m.evaluate("getComputedStyle(document.querySelector('#dimensions .artifact-preview')).position")=="relative")
    ok("mobile detail full height",m.evaluate("document.querySelector('#dimensions .artifact-preview').scrollHeight<=document.querySelector('#dimensions .artifact-preview').clientHeight+4"))
    ok("mobile map stays visible",m.locator("#dimensions .hex-map").is_visible())
    m.close()
    m=b.new_page(viewport={"width":320,"height":640}); m.goto(BASE+"/reference/",wait_until="networkidle")
    ok("mobile 320 no overflow",m.evaluate("document.documentElement.scrollWidth-window.innerWidth")==0); m.close()
    m=b.new_page(viewport={"width":1440,"height":950}); m.emulate_media(reduced_motion="reduce")
    m.goto(BASE+"/reference/",wait_until="networkidle")
    ok("reference static with reduced motion",m.locator("#workflow .step, #artifacts .artifact-node").evaluate_all("els=>els.every(e=>getComputedStyle(e).animationName=='none')") and not m.locator("#artifacts").evaluate("e=>e.classList.contains('is-live')"))
    m.close()
    b.close()
print("\n".join(results)); print("----"); print("TOTAL",len(results),"FAILURES",len(failures)); sys.exit(1 if failures else 0)
